original=(root/'shaders/physics/solve.wgsl').read_text()
helper='''// Artifact-only convergence audit for the single-workgroup joint/contact wave.
var<workgroup> cv_on: u32;
var<workgroup> cv_velocity: atomic<u32>;
var<workgroup> cv_impulse: atomic<u32>;
var<workgroup> cv_stop: u32;
var<workgroup> cv_quiet: u32;
var<workgroup> cv_last_v: f32;
var<workgroup> cv_last_i: f32;
fn cv_change(a:f32,b:f32)->f32 {
    if (!(abs(a)<=3.402823e38) || !(abs(b)<=3.402823e38)) { return bitcast<f32>(0x7f800000u); }
    return abs(b-a)/(1.0+max(abs(a),abs(b)));
}
fn cv_i(a:f32,b:f32) { if(cv_on!=0u) { atomicMax(&cv_impulse,bitcast<u32>(cv_change(a,b))); } }
fn cv_i3(a:vec3<f32>,b:vec3<f32>) { for(var i=0u;i<3u;i++){cv_i(a[i],b[i]);} }
fn cv_b(a:Body,b:Body) {
    if(cv_on!=0u) { for(var i=0u;i<3u;i++) {
        atomicMax(&cv_velocity,bitcast<u32>(cv_change(a.vel[i],b.vel[i])));
        atomicMax(&cv_velocity,bitcast<u32>(cv_change(a.omega[i],b.omega[i])));
    } }
}
fn cv_j(a:Joint,b:Joint) {
    if(cv_on==0u){return;}
    cv_i(a.impulse,b.impulse);cv_i(a.spring_impulse,b.spring_impulse);
    cv_i(a.motor_impulse,b.motor_impulse);cv_i(a.lower_impulse,b.lower_impulse);
    cv_i(a.upper_impulse,b.upper_impulse);cv_i(a.swing_impulse,b.swing_impulse);
    cv_i(a.perp_impulse.x,b.perp_impulse.x);cv_i(a.perp_impulse.y,b.perp_impulse.y);
    cv_i3(a.angular_impulse,b.angular_impulse);
    cv_i3(a.spring_angular_impulse,b.spring_angular_impulse);
    cv_i3(a.motor_angular_impulse,b.motor_angular_impulse);
    cv_i3(a.weld_linear_impulse,b.weld_linear_impulse);
    cv_i3(a.weld_angular_impulse,b.weld_angular_impulse);
}
fn cv_c(a:Contact,b:Contact) {
    if(cv_on==0u){return;}
    cv_i(a.rb0.w,b.rb0.w);cv_i(a.rb1.w,b.rb1.w);cv_i(a.rb2.w,b.rb2.w);cv_i(a.rb3.w,b.rb3.w);
    cv_i(a.friction_impulse.x,b.friction_impulse.x);cv_i(a.friction_impulse.y,b.friction_impulse.y);
    cv_i(a.twist_impulse,b.twist_impulse);cv_i3(a.rolling_impulse,b.rolling_impulse);
    // This monotonic accumulator is consumed only by a zero/nonzero restitution gate.
    // Its magnitude is not a fixed-point impulse; preserve and monitor the consumed state.
    for(var i=0u;i<4u;i++){
        cv_i(select(0.0,1.0,a.total_normal_impulse[i]!=0.0),select(0.0,1.0,b.total_normal_impulse[i]!=0.0));
    }
}
fn cv_report(iterations:u32) {
    var carrier=0u;
    for(var i=0u;i<params.joint_count;i++) {
        var j=joints[i];if(j.kind!=JOINT_FILTER){continue;}
        if(j.revolute_axes_step!=params.physics_step) {
            j.revolute_axes_step=params.physics_step;
            j.weld_linear_impulse=vec3<f32>(0.0);
            j.spring_angular_impulse=vec3<f32>(0.0);
            j.motor_angular_impulse=vec3<f32>(0.0);
            j.angular_impulse=vec3<f32>(0.0);
        }
        let index=u32(j.weld_linear_impulse.x);
        var value=f32(iterations);
        if(carrier==1u){value=cv_last_v;}if(carrier==2u){value=cv_last_i;}
        if(index<3u){j.spring_angular_impulse[index]=value;}
        else if(index<6u){j.motor_angular_impulse[index-3u]=value;}
        else if(index<8u){j.angular_impulse[index-6u]=value;}
        j.weld_linear_impulse.x+=1.0;
        j.weld_linear_impulse.y+=select(1.0,0.0,cv_quiet>=2u);
        j.weld_linear_impulse.z=f32(params.use_bias);
        joints[i]=j;carrier++;
        if(carrier==3u){break;}
    }
}

