def difference(a,b,path='$'):
    if type(a) is not type(b): return path,a,b
    if isinstance(a,dict):
        if a.keys()!=b.keys(): return path+'.keys',sorted(a),sorted(b)
        for k in sorted(a):
            d=difference(a[k],b[k],path+'.'+k)
            if d:return d
    elif isinstance(a,list):
